def is_name_start(c): return c.isalpha() or c=='_'
def is_name_char(c): return c.isalnum() or c=='_'

def matching_brace(s, i):
    # i points just after "${"
    depth=1; j=i
    sq=dq=False
    while j < len(s):
        c=s[j]
        if sq:
            if c=="'": sq=False
        elif dq:
            if c=='\\': j+=1
            elif c=='"': dq=False
        else:
            if c=="'": sq=True
            elif c=='"': dq=True
            elif c=='{': depth+=1
            elif c=='}':
                depth-=1
                if depth==0: return j
            elif c=='\\': j+=1
        j+=1
    return -1

def matching_paren(s, i):
    # i points just after opening paren; return index of matching )
    depth=1; j=i
    sq=dq=False; bt=False
    while j < len(s):
        c=s[j]
        if bt:
            if c=='\\': j+=1
            elif c=='`': bt=False
        elif sq:
            if c=="'": sq=False
        elif dq:
            if c=='\\': j+=1
            elif c=='"': dq=False
            elif c=='`': bt=True
            elif c=='$' and j+1<len(s) and s[j+1]=='(':
                k=matching_paren(s,j+2)
                if k<0: return -1
                j=k
            elif c=='$' and j+1<len(s) and s[j+1]=='{':
                k=matching_brace(s,j+2)
                if k<0: return -1
                j=k
        else:
            if c=="'": sq=True
            elif c=='"': dq=True
            elif c=='`': bt=True
            elif c=='$' and j+1<len(s) and s[j+1]=='(':
                k=matching_paren(s,j+2)
                if k<0: return -1
                j=k
            elif c=='$' and j+1<len(s) and s[j+1]=='{':
                k=matching_brace(s,j+2)
                if k<0: return -1
                j=k
            elif c=='(':
                depth+=1
            elif c==')':
                depth-=1
                if depth==0: return j
            elif c=='\\': j+=1
