#!/usr/bin/env python3
import sys, os, re, difflib

HELP = """Shellharden: The corrective bash syntax highlighter.

Usage:
	shellharden [options] [files]
	cat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
	--suggest         Output a colored diff suggesting changes.
	--syntax          Output syntax highlighting with ANSI colors.
	--syntax-suggest  Diff with syntax highlighting (default mode).
	--transform       Output suggested changes.
	--check           No output; exit with 2 if changes are suggested.
	--replace         Replace file contents with suggested changes.
	--                Don't treat further arguments as options.
	-h|--help         Show help text.
	--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md

"""
VERSION = "4.3.1\n"

RESET='\033[m'; GREEN='\033[0;42m'; REDBG='\033[0;41m'
C_CMD='\033[0;38;2;192;0;128m'; C_VAR='\033[0;38;2;63;127;207m'; C_ASSIGN='\033[0;38;2;0;127;255m'
C_DQ='\033[0;38;2;255;0;0m'; C_SQ='\033[0;38;2;255;204;85m'; C_KW='\033[0;1m'; C_ESC='\033[0;1;38;2;255;0;128m'

class Pitfall(Exception):
    def __init__(self, line, col, token):
        self.line=line; self.col=col; self.token=token

class UnexpectedEOF(Exception):
    pass

def is_name_start(c): return c.isalpha() or c=='_'
def is_name_char(c): return c.isalnum() or c=='_'

def matching_brace(s, i):
    # i points just after "${"
    depth=1; j=i
    sq=dq=False
    while j < len(s):
        c=s[j]
        if sq:
            if c=="'": sq=False
        elif dq:
            if c=='\\': j+=1
            elif c=='"': dq=False
        else:
            if c=="'": sq=True
            elif c=='"': dq=True
            elif c=='{': depth+=1
            elif c=='}':
                depth-=1
                if depth==0: return j
            elif c=='\\': j+=1
        j+=1
    return -1

def matching_paren(s, i):
    # i points just after opening paren; return index of matching )
    depth=1; j=i
    sq=dq=False; bt=False
    while j < len(s):
        c=s[j]
        if bt:
            if c=='\\': j+=1
            elif c=='`': bt=False
        elif sq:
            if c=="'": sq=False
        elif dq:
            if c=='\\': j+=1
            elif c=='"': dq=False
            elif c=='`': bt=True
            elif c=='$' and j+1<len(s) and s[j+1]=='(':
                k=matching_paren(s,j+2)
                if k<0: return -1
                j=k
            elif c=='$' and j+1<len(s) and s[j+1]=='{':
                k=matching_brace(s,j+2)
                if k<0: return -1
                j=k
        else:
            if c=="'": sq=True
            elif c=='"': dq=True
            elif c=='`': bt=True
            elif c=='$' and j+1<len(s) and s[j+1]=='(':
                k=matching_paren(s,j+2)
                if k<0: return -1
                j=k
            elif c=='$' and j+1<len(s) and s[j+1]=='{':
                k=matching_brace(s,j+2)
                if k<0: return -1
                j=k
            elif c=='(':
                depth+=1
            elif c==')':
                depth-=1
                if depth==0: return j
            elif c=='\\': j+=1
        j+=1
    return -1

def find_backtick(s, i):
    j=i
    while j < len(s):
        if s[j]=='\\': j+=2; continue
        if s[j]=='`': return j
        j+=1
    return -1

class Chunk:
    __slots__=('kind','text','name','orig_braced','simple','inner')
    def __init__(self, kind, text, name=None, orig_braced=False, simple=False, inner=None):
        self.kind=kind; self.text=text; self.name=name; self.orig_braced=orig_braced; self.simple=simple; self.inner=inner

def transform_command_inner(inner):
    # Command substitutions are mini scripts.  Preserve absence of trailing newline.
    out, changed = transform_script(inner, source='', forgiving=True)
    return out

def process_double(inner, line='', basecol=0):
    # Only the conservative style normalization Shellharden does for a whole quoted identifier.
    m=re.fullmatch(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}', inner)
    if m:
        return '"$'+m.group(1)+'"'
    res=[]; i=0
    while i < len(inner):
        c=inner[i]
        if c=='`':
            k=find_backtick(inner,i+1)
            if k<0: raise UnexpectedEOF()
            res.append('$('+transform_command_inner(inner[i+1:k])+')')
            i=k+1; continue
        if c=='$' and i+1<len(inner) and inner[i+1]=='(':
            if i+2<len(inner) and inner[i+2]=='(':
                k=inner.find('))',i+3)
                if k<0: raise UnexpectedEOF()
                res.append(inner[i:k+2]); i=k+2; continue
            k=matching_paren(inner,i+2)
            if k<0: raise UnexpectedEOF()
            res.append('$('+transform_command_inner(inner[i+2:k])+')')
            i=k+1; continue
        if c=='$' and i+1<len(inner) and inner[i+1].isdigit():
            j=i+2
            if j<len(inner) and is_name_char(inner[j]):
                raise Pitfall(line, basecol+i, inner[i:j+1])
        res.append(c); i+=1
    return '"'+''.join(res)+'"'

def braced_chunk(content):
    # A few parameter expansions are already safe/intentional and are not quoted.
    if content.startswith('#') or (content.startswith('!') and (content.endswith('*') or content.endswith('@'))):
        return Chunk('noquote','${'+content+'}')
    if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', content):
        return Chunk('q','$'+content,name=content,orig_braced=True,simple=True)
    if re.fullmatch(r'[0-9]+', content):
        return Chunk('q','${'+content+'}',name=content,orig_braced=True,simple=False)
    m=re.fullmatch(r'([A-Za-z_][A-Za-z0-9_]*)\[\*\]', content)
    if m:
        return Chunk('q','${'+m.group(1)+'[@]}',orig_braced=True,simple=False)
    return Chunk('q','${'+content+'}',orig_braced=True,simple=False)

def parse_word_chunks(w, line='', offset=0):
    chunks=[]; i=0
    while i < len(w):
        c=w[i]
        if c=="'":
            k=w.find("'",i+1)
            if k<0: raise UnexpectedEOF()
            chunks.append(Chunk('sq',w[i:k+1])); i=k+1; continue
        if c=='"':
            # find matching double quote respecting substitutions inside
            j=i+1
            while j<len(w):
                if w[j]=='\\': j+=2; continue
                if w[j]=='"': break
                if w[j]=='$' and j+1<len(w) and w[j+1]=='(':
                    if j+2<len(w) and w[j+2]=='(':
                        k=w.find('))',j+3)
                        if k<0: raise UnexpectedEOF()
                        j=k+2; continue
                    k=matching_paren(w,j+2)
                    if k<0: raise UnexpectedEOF()
                    j=k+1; continue
                if w[j]=='$' and j+1<len(w) and w[j+1]=='{':
                    k=matching_brace(w,j+2)
                    if k<0: raise UnexpectedEOF()
                    j=k+1; continue
                j+=1
            if j>=len(w): raise UnexpectedEOF()
            inner=w[i+1:j]
            chunks.append(Chunk('dq',process_double(inner,line,offset+i+1),inner=process_double(inner,line,offset+i+1)[1:-1]))
            i=j+1; continue
        if c=='\\':
            if i+1<len(w): chunks.append(Chunk('lit',w[i:i+2])); i+=2
            else: chunks.append(Chunk('lit',c)); i+=1
            continue
        if (c=='<' or c=='>') and i+1<len(w) and w[i+1]=='(':
            k=matching_paren(w,i+2)
            if k<0: raise UnexpectedEOF()
            chunks.append(Chunk('noquote',c+'('+transform_command_inner(w[i+2:k])+')'))
            i=k+1; continue
        if c=='`':
            k=find_backtick(w,i+1)
            if k<0: raise UnexpectedEOF()
            chunks.append(Chunk('q','$('+transform_command_inner(w[i+1:k])+')'))
            i=k+1; continue
        if c=='$':
            if i+1>=len(w):
                chunks.append(Chunk('lit','$')); i+=1; continue
            n=w[i+1]
            if n=='(':
                if i+2<len(w) and w[i+2]=='(':
                    k=w.find('))',i+3)
                    if k<0: raise UnexpectedEOF()
                    chunks.append(Chunk('noquote',w[i:k+2])); i=k+2; continue
                k=matching_paren(w,i+2)
                if k<0: raise UnexpectedEOF()
                chunks.append(Chunk('q','$('+transform_command_inner(w[i+2:k])+')'))
                i=k+1; continue
            if n=='{':
                k=matching_brace(w,i+2)
                if k<0: raise UnexpectedEOF()
                chunks.append(braced_chunk(w[i+2:k])); i=k+1; continue
            if is_name_start(n):
                j=i+2
                while j<len(w) and is_name_char(w[j]): j+=1
                name=w[i+1:j]
                chunks.append(Chunk('q','$'+name,name=name,simple=True)); i=j; continue
            if n.isdigit():
                j=i+2
                if j<len(w) and is_name_char(w[j]):
                    while j<len(w) and is_name_char(w[j]): j+=1
                    raise Pitfall(line, offset+i, w[i:j])
                chunks.append(Chunk('q','$'+n,name=n,simple=False)); i+=2; continue
            if n in ('@','*'):
                # unquoted $* is transformed to "$@"; ${*} is intentionally preserved elsewhere.
                chunks.append(Chunk('q','$@')); i+=2; continue
            if n in ('-','_'):
                chunks.append(Chunk('q','$'+n,name=n,simple=False)); i+=2; continue
            if n in ('#','?','$','!'):
                chunks.append(Chunk('noquote','$'+n)); i+=2; continue
            chunks.append(Chunk('lit','$')); i+=1; continue
        # ordinary literal run
        j=i+1
        while j<len(w) and w[j] not in "'\"\\$`":
            if (w[j] in '<>') and j+1<len(w) and w[j+1]=='(':
                break
            j+=1
        chunks.append(Chunk('lit',w[i:j])); i=j
    return chunks

def safe_middle(s):
    # Do not quote through glob metacharacters, escapes, or '%' (which Shellharden keeps outside).
    return s!='' and not any(ch in s for ch in '*?[\\%')

def first_plain_char_from_chunk(ch):
    if ch.kind=='lit' and ch.text: return ch.text[0]
    if ch.kind=='dq' and ch.inner: return ch.inner[0]
    return ''

def render_expansion(ch, next_char=''):
    if ch.simple and ch.name and (next_char and (next_char.isalnum() or next_char=='_')):
        return '${'+ch.name+'}'
    return ch.text

def transform_word(w, line='', offset=0):
    chunks=parse_word_chunks(w,line,offset)
    if not any(c.kind=='q' for c in chunks):
        return ''.join(c.text for c in chunks)
    out=[]; i=0
    n=len(chunks)
    while i<n:
        ch=chunks[i]
        if ch.kind!='q':
            out.append(ch.text); i+=1; continue
        # Build a quoted span.  Include safe literals only when another expansion follows;
        # include immediately-following double-quoted chunks to mimic Shellharden's quote coalescing.
        span=[]; j=i
        while j<n:
            cj=chunks[j]
            if cj.kind=='q':
                # next char inside span or immediately outside decides whether braces are required
                nxt=''
                if j+1<n:
                    if chunks[j+1].kind=='lit':
                        # If this literal will be part of the span or sits immediately after it,
                        # its first char can require braces.
                        nxt=chunks[j+1].text[:1]
                    elif chunks[j+1].kind=='dq':
                        nxt=chunks[j+1].inner[:1]
                span.append(('q',cj,nxt)); j+=1; continue
            if cj.kind=='lit':
                # include literal only if it connects to a later q without unsafe chars
                k=j+1
                if safe_middle(cj.text):
                    found=False
                    while k<n:
                        if chunks[k].kind=='q': found=True; break
                        if chunks[k].kind=='lit' and safe_middle(chunks[k].text): k+=1; continue
                        break
                    if found:
                        span.append(('text',cj.text,'')); j+=1; continue
                break
            if cj.kind=='dq':
                # Coalesce a double-quoted piece that follows an unquoted expansion.
                span.append(('text',cj.inner,'')); j+=1; continue
            break
        content=[]
        for typ,obj,nxt in span:
            if typ=='text': content.append(obj)
            else: content.append(render_expansion(obj,nxt))
        out.append('"'+''.join(content)+'"')
        i=j
    return ''.join(out)

# tokenization for a single physical line (newline stripped)
def tokenize(line):
    toks=[]; i=0; at_word_start=True
    while i<len(line):
        c=line[i]
        if c in ' \t\r':
            j=i+1
            while j<len(line) and line[j] in ' \t\r': j+=1
            toks.append(('space',line[i:j],i)); i=j; at_word_start=True; continue
        if c=='#' and at_word_start:
            toks.append(('comment',line[i:],i)); break
        # operators
        if line.startswith(';&',i) or line.startswith(';;',i) or line.startswith('&&',i) or line.startswith('||',i):
            toks.append(('op',line[i:i+2],i)); i+=2; at_word_start=True; continue
        if c in ';|()':
            toks.append(('op',c,i)); i+=1; at_word_start=True; continue
        # word; respect quotes/substitutions; don't split redirection constructs
        j=i
        while j<len(line):
            c=line[j]
            if c in ' \t\r': break
            if c=='#' and (j==i): break
            if c in ';|()':
                # Parentheses can be part of process/command substitutions handled below; otherwise split.
                break
            if c=="'":
                k=line.find("'",j+1)
                if k<0: raise UnexpectedEOF()
                j=k+1; continue
            if c=='"':
                k=j+1
                while k<len(line):
                    if line[k]=='\\': k+=2; continue
                    if line[k]=='"': break
                    if line[k]=='$' and k+1<len(line) and line[k+1]=='(':
                        if k+2<len(line) and line[k+2]=='(':
                            q=line.find('))',k+3)
                            if q<0: raise UnexpectedEOF()
                            k=q+2; continue
                        q=matching_paren(line,k+2)
                        if q<0: raise UnexpectedEOF()
                        k=q+1; continue
                    if line[k]=='$' and k+1<len(line) and line[k+1]=='{':
                        q=matching_brace(line,k+2)
                        if q<0: raise UnexpectedEOF()
                        k=q+1; continue
                    k+=1
                if k>=len(line): raise UnexpectedEOF()
                j=k+1; continue
            if c=='`':
                k=find_backtick(line,j+1)
                if k<0: raise UnexpectedEOF()
                j=k+1; continue
            if c=='$' and j+1<len(line) and line[j+1]=='(':
                if j+2<len(line) and line[j+2]=='(':
                    k=line.find('))',j+3)
                    if k<0: raise UnexpectedEOF()
                    j=k+2; continue
                k=matching_paren(line,j+2)
                if k<0: raise UnexpectedEOF()
                j=k+1; continue
            if c in '<>' and j+1<len(line) and line[j+1]=='(':
                k=matching_paren(line,j+2)
                if k<0: raise UnexpectedEOF()
                j=k+1; continue
            if c=='$' and j+1<len(line) and line[j+1]=='{':
                k=matching_brace(line,j+2)
                if k<0: raise UnexpectedEOF()
                j=k+1; continue
            if c=='\\':
                j+=2; continue
            j+=1
        toks.append(('word',line[i:j],i)); i=j; at_word_start=False
    return toks

def word_indices(toks): return [i for i,t in enumerate(toks) if t[0]=='word']
def is_assignment_word(w): return re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', w) is not None

def transform_test_tokens(toks):
    wis=word_indices(toks)
    if not wis: return None
    words=[toks[i][1] for i in wis]
    if words[0]=='[' and words[-1]==']' and len(words)==4 and words[1] in ('-n','-z'):
        arg=transform_word(words[2], toks[wis[2]][1], toks[wis[2]][2])
        op='!=' if words[1]=='-n' else '='
        # Preserve conventional single spaces for this canonical rewrite.
        return '[ '+arg+' '+op+' "" ]'
    if words[0]=='test' and len(words)==3 and words[1] in ('-n','-z'):
        arg=transform_word(words[2], toks[wis[2]][1], toks[wis[2]][2])
        op='!=' if words[1]=='-n' else '='
        return 'test '+arg+' '+op+' ""'
    return None

def transform_line(line):
    toks=tokenize(line)
    repl=transform_test_tokens(toks)
    if repl is not None:
        return repl
    out=[t[1] for t in toks]
    wis=word_indices(toks)

    # [[ ... ]] and arithmetic compound commands: leave their words alone.
    skip=set()
    for pos,idx in enumerate(wis):
        w=toks[idx][1]
        if w=='[[':
            for j in wis[pos:]:
                skip.add(j)
                if toks[j][1]==']]': break
        if w=='((':
            for j in wis[pos:]:
                skip.add(j)
                if toks[j][1]=='))': break

    # case expression and patterns are not word-splitting contexts.
    for pos,idx in enumerate(wis):
        if toks[idx][1]=='case' and pos+1<len(wis):
            skip.add(wis[pos+1])
        if toks[idx][1]=='in' and pos>0:
            # The first word before a ) in a case arm is a pattern; conservatively skip until )/;;
            pass

    # for-loop variable/list handling on the same physical line.
    for pos,idx in enumerate(wis):
        if toks[idx][1]=='for' and pos+1<len(wis):
            skip.add(wis[pos+1])
            if pos+2<len(wis) and toks[wis[pos+2]][1]=='in':
                # list words until ; or do
                list_w=[]; p=pos+3
                while p<len(wis):
                    # any op between previous and this that is ; ends list
                    between=toks[wis[p-1]+1:wis[p]] if p>pos+3 else toks[wis[pos+2]+1:wis[p]]
                    if any(t[0]=='op' and t[1]==';' for t in between): break
                    if toks[wis[p]][1]=='do': break
                    list_w.append(wis[p]); p+=1
                if len(list_w)==1:
                    raw=toks[list_w[0]][1]
                    m=re.fullmatch(r'\$([A-Za-z_][A-Za-z0-9_]*)', raw)
                    mb=re.fullmatch(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\[@\]\}', raw)
                    if m:
                        out[list_w[0]]='"${'+m.group(1)+'[@]}"'; skip.add(list_w[0])
                    elif mb:
                        out[list_w[0]]='"${'+mb.group(1)+'[@]}"'; skip.add(list_w[0])

    # Heredoc operator targets are delimiters, not words to quote.
    heredoc_next=False
    cmd_start=True; cmd_name=None; declaration_noquote=False; declare_option_seen=False
    for ti,(typ,text,col) in enumerate(toks):
        if typ=='op':
            if text in (';','|','&&','||'):
                cmd_start=True; cmd_name=None; declaration_noquote=False; declare_option_seen=False
            continue
        if typ!='word': continue
        if ti in skip: continue
        if heredoc_next:
            heredoc_next=False; continue
        if text.startswith('<<') and not text.startswith('<<<'):
            # delimiter may be attached to the operator (<<EOF) or be next word
            if text in ('<<','<<-'): heredoc_next=True
            continue
        # command-start assignment prefixes are safe as-is.
        if cmd_start and is_assignment_word(text):
            cmd_start=True; continue
        if cmd_start:
            cmd_name=text; cmd_start=False
            # transform command word too if it contains expansions
            out[ti]=transform_word(text,line,col)
            declaration_noquote = cmd_name in ('export','local','readonly') or cmd_name=='declare'
            declare_option_seen=False
            continue
        if declaration_noquote and is_assignment_word(text):
            # export/local/readonly and bare declare do not need RHS quotes; declare with options does.
            if cmd_name=='declare' and declare_option_seen:
                out[ti]=transform_word(text,line,col)
            else:
                out[ti]=text
            continue
        if declaration_noquote and text.startswith('-'):
            declare_option_seen=True
            continue
        out[ti]=transform_word(text,line,col)
    return ''.join(out)

def detect_heredocs(line):
    res=[]
    # Simple, common heredoc forms.  Strip quotes around the delimiter.
    for m in re.finditer(r'<<-?\s*(["\']?)([A-Za-z0-9_.-]+)\1', line):
        if line[m.start():].startswith('<<<'): continue
        res.append(m.group(2))
    return res

def transform_script(text, source='', forgiving=False):
    out=[]; changed=False; heredocs=[]
    # splitlines preserving endings
    parts=text.splitlines(True)
    if not parts and text=='': return '', False
    for part in parts:
        nl=''
        body=part
        if body.endswith('\n'):
            nl='\n'; body=body[:-1]
        if heredocs:
            out.append(body+nl)
            if body.strip()==heredocs[0]: heredocs.pop(0)
            continue
        try:
            tb=transform_line(body)
        except Pitfall:
            raise
        except UnexpectedEOF:
            if forgiving:
                tb=body
            else:
                raise
        out.append(tb+nl)
        if tb!=body: changed=True
        heredocs.extend(detect_heredocs(body))
    return ''.join(out), changed

def pitfall_message(source, line, col, token):
    caret=' '*col + '^'*max(1,len(token))
    prefix=source
    return (f"{prefix}: Unsupported syntax: Syntactic pitfall\n"
            f"{line}\n{caret}\n"
            "This does not mean what it looks like. You may be forgiven to think that the full string of numerals is the variable name. Only the fist is.\n\n"
            "Try this and be shocked: f() { echo \"$9\" \"$10\"; }; f a b c d e f g h i j\n\n"
            "Here is where braces should be used to disambiguate, e.g. \"${10}\" vs \"${1}0\".\n\n"
            "Syntactic pitfalls are deemed too dangerous to fix automatically\n"
            "(the purpose of Shellharden is to fix vulnerable code – code that mostly does what it looks like, as opposed to code that never does what it looks like):\n"
            "* Fixing what it does would be 100% subtle and might slip through code review unnoticed.\n"
            "* Fixing its look would make a likely bug look intentional.\n")

def eof_message(source):
    return (f"{source}: Unexpected end of file\n"
            "The file's end was reached without closing all sytactic scopes.\n"
            "Either, the parser got lost, or the file is truncated or malformed.\n")

def suggest_markup(orig, trans):
    sm=difflib.SequenceMatcher(a=orig,b=trans,autojunk=False)
    out=[]
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=='equal': out.append(orig[i1:i2])
        elif tag=='delete': out.append(REDBG+orig[i1:i2]+RESET)
        elif tag=='insert': out.append(GREEN+trans[j1:j2]+RESET)
        elif tag=='replace':
            out.append(REDBG+orig[i1:i2]+RESET)
            out.append(GREEN+trans[j1:j2]+RESET)
    return ''.join(out)

KEYWORDS={'for','do','done','if','then','fi','while','until','case','in','esac','else','elif','function','select'}

def highlight_word(w, command=False):
    chunks=[]; i=0
    # assignment lhs coloring
    m=re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(=)', w)
    if m:
        return C_ASSIGN+m.group(1)+RESET+w[m.end(1):]
    if w in KEYWORDS:
        return C_KW+w+RESET
    # basic variable/string coloring
    out=[]; i=0
    while i<len(w):
        if w[i]=="'":
            k=w.find("'",i+1)
            if k<0: k=len(w)-1
            out.append(C_SQ+w[i:k+1]+RESET); i=k+1; continue
        if w[i]=='"':
            out.append(C_DQ+'"'+RESET); i+=1; continue
        if w[i]=='\\' and i+1<len(w):
            out.append(C_ESC+w[i:i+2]+RESET); i+=2; continue
        if w[i]=='$':
            if i+1<len(w) and w[i+1]=='{':
                k=matching_brace(w,i+2)
                if k>=0:
                    out.append(C_VAR+w[i:k+1]+RESET); i=k+1; continue
            if i+1<len(w) and is_name_start(w[i+1]):
                j=i+2
                while j<len(w) and is_name_char(w[j]): j+=1
                out.append(C_VAR+w[i:j]+RESET); i=j; continue
            if i+1<len(w) and (w[i+1].isdigit() or w[i+1] in '@*#?$!-_'):
                out.append(C_VAR+w[i:i+2]+RESET); i+=2; continue
        out.append(w[i]); i+=1
    s=''.join(out)
    if command and not w.startswith('$') and w not in KEYWORDS:
        return C_CMD+s+RESET
    return s

def syntax_highlight(text):
    res=[]
    for part in text.splitlines(True):
        nl=''
        body=part
        if body.endswith('\n'): nl='\n'; body=body[:-1]
        try: toks=tokenize(body)
        except Exception:
            res.append(body+nl); continue
        cmd_start=True
        for typ,val,col in toks:
            if typ=='word':
                res.append(highlight_word(val, command=cmd_start and not is_assignment_word(val)))
                if not is_assignment_word(val): cmd_start=False
            else:
                res.append(val)
                if typ=='op' and val in (';','|','&&','||'): cmd_start=True
        res.append(nl)
    return ''.join(res)

def process_content(data, mode, source=''):
    try:
        trans, changed = transform_script(data, source=source)
    except Pitfall as e:
        # Partial behavior: transform text preceding the failing token's line approximately.
        raise
    if mode=='transform' or mode=='replace': return trans, changed
    if mode=='check': return '', changed
    if mode=='suggest': return suggest_markup(data, trans), changed
    if mode=='syntax': return syntax_highlight(data), changed
    # syntax-suggest/default: highlight the suggested result; additions are not exact, but useful.
    return syntax_highlight(suggest_markup(data, trans)), changed

def main(argv):
    mode='syntax-suggest'; files=[]; output_prefix=[]; parse_opts=True
    for a in argv[1:]:
        if parse_opts and a=='--': parse_opts=False; continue
        if parse_opts and a.startswith('-') and a!='':
            if a in ('-h','--help'):
                output_prefix.append(HELP); continue
            if a=='--version': output_prefix.append(VERSION); continue
            if a=='--suggest': mode='suggest'; continue
            if a=='--syntax': mode='syntax'; continue
            if a=='--syntax-suggest': mode='syntax-suggest'; continue
            if a=='--transform': mode='transform'; continue
            if a=='--check': mode='check'; continue
            if a=='--replace': mode='replace'; continue
            sys.stderr.write(f"{a}: No such option.\n"); return 3
        files.append(a)
    rc=0; any_changed=False
    if output_prefix and mode!='check':
        sys.stdout.write(''.join(output_prefix))
    # No file arguments means no stdin processing.
    for path in files:
        if path=='':
            data=sys.stdin.read()
            source=''
            try:
                out, changed=process_content(data, 'transform' if mode=='replace' else mode, source)
                any_changed = any_changed or changed
                if mode!='check': sys.stdout.write(out)
            except Pitfall as e:
                # best effort partial line prefix
                prefix=e.line[:e.col]
                if mode in ('transform','replace'):
                    sys.stdout.write(prefix+'\n')
                sys.stderr.write(pitfall_message(source,e.line,e.col,e.token)); rc=max(rc,1)
            except UnexpectedEOF:
                if mode in ('transform','replace'):
                    sys.stdout.write(data+'\n')
                sys.stderr.write(eof_message(source)); rc=max(rc,1)
            continue
        try:
            with open(path,'r',encoding='utf-8',errors='surrogateescape') as f: data=f.read()
        except OSError as e:
            sys.stderr.write(f"{path}: {e.strerror} (os error {e.errno})\n"); rc=max(rc,1); continue
        try:
            out, changed=process_content(data, mode, path)
            any_changed = any_changed or changed
            if mode=='replace':
                if changed:
                    with open(path,'w',encoding='utf-8',errors='surrogateescape') as f: f.write(out)
            elif mode!='check':
                sys.stdout.write(out)
        except Pitfall as e:
            if mode in ('transform','replace'):
                sys.stdout.write(e.line[:e.col]+'\n')
            sys.stderr.write(pitfall_message(path,e.line,e.col,e.token)); rc=max(rc,1)
        except UnexpectedEOF:
            if mode in ('transform','replace'):
                sys.stdout.write(data+'\n')
            sys.stderr.write(eof_message(path)); rc=max(rc,1)
    if mode=='check' and any_changed:
        rc=max(rc,2)
    return rc

if __name__=='__main__':
    sys.exit(main(sys.argv))
